"""Offline smoke test with the Sunday release: compile_case, compile_evidence, signals, planner_hints.

usage: python smoke_release.py <repo> <package dir> <release dir>
"""

import json
import logging
import sys
import traceback
from pathlib import Path

repo, root, release = (Path(a) for a in sys.argv[1:4])
sys.path.insert(0, str(repo))

from arena_kit.data import DataPackage  # noqa: E402

from hollerau.evidence.adapter import planner_hints  # noqa: E402
from hollerau.evidence.compile import compile_evidence  # noqa: E402
from hollerau.evidence.economics import compile_case  # noqa: E402
from hollerau.evidence.signals import signals  # noqa: E402


class Count(logging.Handler):
    def __init__(self):
        super().__init__(logging.ERROR)
        self.records = []

    def emit(self, record):
        self.records.append(record)


errors = Count()
logging.getLogger().addHandler(errors)

data = DataPackage(root, release)
assert data.release is not None, "release not loaded"
release_ids = set(json.loads((release / "facts.json").read_text(encoding="utf-8")))
print(f"package {data.root}\nrelease {data.release}: {len(release_ids)} new IDs")

cases = []
for name in ("practice.json", "sandbox.json"):
    cases += json.loads((repo / "tests/fixtures/cases" / name).read_text())

raised, cited, context = [], [], []
for case in cases:
    cid = case["case_id"]
    for fn, call in (
        ("compile_case", lambda: compile_case(case, None, data)),
        ("compile_evidence", lambda: compile_evidence(case, data)),
        ("signals", lambda: signals(case, data)),
        ("planner_hints", lambda: planner_hints(case, data)),
    ):
        try:
            out = call()
        except Exception as e:
            raised.append((cid, fn, repr(e)))
            traceback.print_exc()
            continue
        if fn == "compile_evidence":
            for c in out:
                hit = sorted(set(c.ids) & release_ids)
                if hit:
                    cited.append((cid, c.family, hit, c.sentence[:140]))
        if fn == "signals":
            for sup, sig in (out.get("suppliers") or {}).items():
                for k, v in sig.items():
                    if isinstance(v, list):
                        hit = sorted(set(map(str, v)) & release_ids)
                        if hit:
                            context.append((cid, sup, k, hit))

print(f"\ncases: {len(cases)}  raised: {len(raised)}  logged errors: {len(errors.records)}")
for r in raised:
    print("RAISED", *r)
for r in errors.records:
    print("LOGGED", r.getMessage()[:160])
print(f"\nclaims citing a release ID: {len(cited)}")
for cid, fam, hit, s in cited:
    print(f"  {cid} {fam} {hit} :: {s}")
print(f"\nsignals (context, not claims) sourced from the release: {len(context)}")
for row in context:
    print("  ", *row)

