"""Offline evaluation of a supplier model: from the supplier's first counter-offer, predict its floor.

Reads the archived sessions in analysis/pegasus_data/sessions/ only. No session, no network.

  floor     the unit price implied by c_best: the highest price that reaches c_best at some allowed
            structure (must-haves kept, the supplier's opening terms as its standard). C is linear in the
            price only without a relationship cost: relationship cases are left out, except P10 (no
            relationship cost was charged on our deals there, as in "Coûts de référence par cas").
  rows      one per session and supplier thread with a first counter-offer: opening price p0, first
            counter-offer p1, last price (deal or last offer). In an RFQ only the thread of the supplier
            with the lowest implied floor is kept: c_best is the best supplier's, the others' floors are unknown.
  model     y = floor / p0, from x = p1 / p0 and the category goal (least squares, small ridge), fitted
            leaving one case out. Reference: the median y of the other cases.
  criterion written before in hollerau/evidence/OPPONENT_MODEL.md: median error <= 2 % of the opening
            price, better than the reference on >= 7 cases out of 10, never more than 3 % above the true floor.

usage: uv run python analysis/opponent_eval.py
"""

import itertools
import json
import statistics
from collections import defaultdict
from pathlib import Path

from arena_kit import cost as kit

ROOT = Path(__file__).resolve().parent.parent
SESSIONS = ROOT / "analysis" / "pegasus_data" / "sessions"
FIXTURES = ROOT / "tests" / "fixtures" / "cases"
LINEAR_DESPITE_RELATIONSHIP = {"case:P10"}
GOALS = ("leverage", "routine", "quality_first", "secure_supply")
RIDGE = 1e-3
MAX_ERR, MAX_ABOVE, MIN_WINS = 0.02, 0.03, 7
VAULT_FLOOR = {"case:P04": 4.93, "case:P05": 26.64, "case:P07": 5.02, "case:P08": 5.10, "case:P11": 43.90, "case:P18": 4.73}


def cases():
    out = {}
    for name in ("practice.json", "sandbox.json"):
        out |= {c["case_id"]: c for c in json.loads((FIXTURES / name).read_text())}
    return out


def linear(case):
    return not case["buyer"].get("relationship_eur_per_point") or case["case_id"] in LINEAR_DESPITE_RELATIONSHIP


def implied_floor(case, std, c_best):
    """The highest unit price with C = c_best at an allowed structure (C is linear in the price here)."""
    opts = case.get("term_options") or {}
    keys = [k for k in opts if k != "unit_price"]
    best = None
    for combo in itertools.product(*(opts[k] for k in keys)):
        structure = dict(zip(keys, combo))
        lo, hi = ({**structure, "unit_price": p} for p in (1.0, 2.0))
        if not kit.must_haves_ok(case, kit.complete_offer(case, lo), std):
            continue
        c1, c2 = kit.total_cost(case, lo, std), kit.total_cost(case, hi, std)
        if not (c2 > c1) or c1 != c1 or c1 == float("inf"):
            continue
        price = 1.0 + (c_best - c1) / (c2 - c1)
        best = price if best is None else max(best, price)
    return best


def supplier_offers(session):
    """{supplier: [(round, unit_price)]} from the trace, the opening included."""
    out = defaultdict(list)
    for e in session["result"].get("trace") or []:
        move = e.get("move") or {}
        if e.get("actor", "").startswith("sup:") and isinstance(move, dict) and (move.get("terms") or {}).get("unit_price"):
            out[e["actor"]].append((int(e["round"]), float(move["terms"]["unit_price"])))
    return out


def rows(all_cases):
    floors, out, skipped = {}, [], defaultdict(int)
    for path in sorted(SESSIONS.glob("*.json")):
        d = json.loads(path.read_text())
        s, cid = d["session"], d["session"]["case_id"]
        case, res = all_cases.get(cid), s.get("result") or {}
        if case is None or not linear(case):
            skipped["relationship case" if case else "unknown case"] += 1
            continue
        if not res.get("c_best"):
            skipped["no result"] += 1
            continue
        threads = []
        for sup, offers in supplier_offers(s).items():
            opening = (s.get("opening") or {}).get(sup) or {}
            std = {k: v for k, v in (opening.get("terms") or {}).items() if k != "unit_price"}
            key = (cid, sup)
            if key not in floors:
                floors[key] = implied_floor(case, std, res["c_best"])
            offers.sort()
            if len(offers) < 2 or offers[0][0] != 0 or floors[key] is None:
                continue
            deal = res.get("terms", {}).get("unit_price") if res.get("supplier_id") == sup and res.get("deal") else None
            threads.append({
                "case": cid, "session": s["session_id"], "supplier": sup, "goal": case["buyer"]["category_goal"],
                "p0": offers[0][1], "p1": offers[1][1], "last": deal or offers[-1][1], "deal": bool(deal),
                "floor": floors[key], "rounds": len(offers) - 1,
            })
        if not threads:
            skipped["no counter-offer"] += 1
            continue
        out.append(min(threads, key=lambda t: t["floor"]))  # RFQ: the best supplier's thread
    return out, floors, skipped


def solve(a, b):
    """Gaussian elimination for a small dense system."""
    n = len(b)
    m = [row[:] + [b[i]] for i, row in enumerate(a)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(m[r][c]))
        m[c], m[p] = m[p], m[c]
        for r in range(n):
            if r != c and m[c][c]:
                f = m[r][c] / m[c][c]
                m[r] = [x - f * y for x, y in zip(m[r], m[c])]
    return [m[i][n] / m[i][i] if m[i][i] else 0.0 for i in range(n)]


def features(r, with_goal):
    x = [1.0, r["p1"] / r["p0"]]
    return x + ([1.0 if r["goal"] == g else 0.0 for g in GOALS[1:]] if with_goal else [])


def fit(train, with_goal):
    xs = [features(r, with_goal) for r in train]
    ys = [r["floor"] / r["p0"] for r in train]
    k = len(xs[0])
    xtx = [[sum(x[i] * x[j] for x in xs) + (RIDGE if i == j and i else 0) for j in range(k)] for i in range(k)]
    xty = [sum(x[i] * y for x, y in zip(xs, ys)) for i in range(k)]
    w = solve(xtx, xty)
    return lambda r: sum(a * b for a, b in zip(w, features(r, with_goal)))


def evaluate(data, with_goal):
    by_case = defaultdict(list)
    for r in data:
        by_case[r["case"]].append(r)
    per_case = {}
    for cid, test in sorted(by_case.items()):
        train = [r for r in data if r["case"] != cid]
        model = fit(train, with_goal)
        ref = statistics.median(statistics.median(r["floor"] / r["p0"] for r in rs) for c, rs in by_case.items() if c != cid)
        err = [model(r) - r["floor"] / r["p0"] for r in test]  # signed, in shares of the opening price
        ref_err = [ref - r["floor"] / r["p0"] for r in test]
        per_case[cid] = {
            "n": len(test), "goal": test[0]["goal"],
            "x": statistics.median(r["p1"] / r["p0"] for r in test),
            "y": statistics.median(r["floor"] / r["p0"] for r in test),
            "pred": statistics.median(model(r) for r in test), "ref": ref,
            "err": statistics.median(abs(e) for e in err), "ref_err": statistics.median(abs(e) for e in ref_err),
            "above": max(err),
        }
    return per_case


def verdict(per_case):
    med = statistics.median(v["err"] for v in per_case.values())
    wins = sum(v["err"] < v["ref_err"] for v in per_case.values())
    above = max(v["above"] for v in per_case.values())
    ok = med <= MAX_ERR and wins >= MIN_WINS and above <= MAX_ABOVE
    return med, wins, above, ok


def main():
    all_cases = cases()
    data, floors, skipped = rows(all_cases)
    print(f"sessions kept: {len(data)}   skipped: {dict(skipped)}")
    print("\nimplied floor (c_best) vs the vault's 'prix pour score 1':")
    for (cid, sup), f in sorted(floors.items()):
        v = VAULT_FLOOR.get(cid)
        print(f"  {cid} {sup}: {f:.2f}" + (f"   vault {v:.2f}" if v else "") if f else f"  {cid} {sup}: none")
    for name, with_goal in (("x + goal (main model)", True), ("x only", False)):
        per_case = evaluate(data, with_goal)
        print(f"\n== {name}: leave one case out, shares of the opening price")
        print("case      goal           n   p1/p0  floor/p0  pred   ref    |err|  |ref err| max above")
        for cid, v in per_case.items():
            print(f"{cid:9} {v['goal']:13} {v['n']:3}  {v['x']:.3f}  {v['y']:.3f}    {v['pred']:.3f}  {v['ref']:.3f}"
                  f"  {v['err']:.3f}  {v['ref_err']:.3f}     {v['above']:+.3f}")
        med, wins, above, ok = verdict(per_case)
        print(f"median |err| {med:.3f} (<= {MAX_ERR})  better than reference on {wins}/{len(per_case)} cases"
              f" (>= {MIN_WINS})  max above {above:+.3f} (<= {MAX_ABOVE})  ->  {'PASS' if ok else 'FAIL'}")


if __name__ == "__main__":
    main()
